// === Lecture brute des entités HA ===
// Getters uniquement, aucune logique métier. Entités configurables dans l'onglet
// Env du flow, valeurs par défaut = installation d'origine.
// PREREQUIS : cocher "Enable global context store" sur le nœud serveur HA.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

let g;
try {
    g = global.get('homeassistant').homeAssistant.states;
    if (!g) throw new Error('states indisponibles');
} catch (e) {
    node.warn('HA indisponible, tick ignoré : ' + e.message);
    return null;
}

const eStr = (k, def) => {
    const v = env.get(k);
    return (v === undefined || v === null || v === '') ? def : String(v);
};
const eNum = (k, def) => {
    const v = parseFloat(env.get(k));
    return isNaN(v) ? def : v;
};
const usable = (raw) => raw !== undefined && raw !== null
    && raw !== 'unavailable' && raw !== 'unknown' && !isNaN(parseFloat(raw));
const numOr = (id, def) => (usable(g[id]?.state) ? parseFloat(g[id].state) : def);
const attrNum = (id, key) => {
    const v = parseFloat(g[id]?.attributes?.[key]);
    return isNaN(v) ? null : v;
};
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const now = Date.now();
msg.now = now;

// --- Entités ---
const ID = {
    switch: eStr('CUMULUS_SWITCH', 'switch.chauffe_eau_electrique'),
    power: eStr('CUMULUS_POWER', 'sensor.chauffe_eau_electrique_power'),
    temp: eStr('WATER_TEMP_SENSOR', 'sensor.temp_chauffe_eau_electrique_temperature'),
    solarTank: eStr('SOLAR_TANK_SENSOR', 'sensor.temp_chauffe_eau_solaire_temperature'),
    solar: eStr('SOLAR_SENSOR', 'sensor.pince_amperemetrique_power_a'),
    grid: eStr('GRID_SENSOR', 'sensor.pince_amperemetrique_power_b'),
    house: eStr('HOUSE_SENSOR', 'sensor.pince_amperemetrique_power_ab'),
    clim: eStr('CLIM_SENSOR', 'sensor.clim_automation'),
    solcastToday: 'sensor.solcast_pv_forecast_previsions_pour_aujourd_hui',
    solcastTomorrow: 'sensor.solcast_pv_forecast_previsions_pour_demain',
    solcastRemaining: 'sensor.solcast_pv_forecast_previsions_de_production_restantes_aujourd_hui',
    solcastField: 'select.solcast_pv_forecast_utiliser_le_champ_de_prevision'
};

msg.switchId = ID.switch;

// --- Constantes de l'installation ---
msg.loadW = clamp(eNum('CUMULUS_LOAD_W', 1200), 100, 10000);
msg.solarMargin = clamp(eNum('SOLAR_SUFFICIENT_MARGIN', 3), 0, 20);

// --- Réglages utilisateur (helpers HA) ---
msg.enabled = g['input_boolean.cumulus_automation_enabled']?.state === 'on';
msg.target = clamp(numOr('input_number.cumulus_target_temp', 55), 30, 75);
msg.minT = clamp(numOr('input_number.cumulus_min_temp', 45), 20, msg.target);
msg.effSetting = clamp(numOr('input_number.cumulus_efficiency', 0.9), 0.3, 1);
msg.tankL = clamp(numOr('input_number.cumulus_tank_volume', 200), 30, 500);
msg.kwhPerDeg = msg.tankL * 4.186 / 3600;   // kWh thermiques par °C

// --- Sonde du ballon électrique (capteur critique) ---
const rawTemp = g[ID.temp]?.state;
msg.tempAvailable = usable(rawTemp);
msg.temp = msg.tempAvailable ? parseFloat(rawTemp) : null;
if (msg.tempAvailable) {
    setF('sondeDownSince', null);
    msg.sondeDownHours = 0;
} else {
    let ds = getF('sondeDownSince');
    if (!ds) { ds = now; setF('sondeDownSince', ds); }
    msg.sondeDownHours = Math.round((now - ds) / 360000) / 10;
}

// --- Ballon solaire en amont (préchauffe en série) ---
const rawSolarTank = g[ID.solarTank]?.state;
msg.solarTankAvailable = usable(rawSolarTank);
msg.solarTankTemp = msg.solarTankAvailable ? parseFloat(rawSolarTank) : null;

// --- Mesures électriques ---
msg.solar = numOr(ID.solar, 0);
msg.gridPower = numOr(ID.grid, 0);           // > 0 import, < 0 export
msg.export = -msg.gridPower;
msg.house = usable(g[ID.house]?.state) ? parseFloat(g[ID.house].state)
    : msg.solar + msg.gridPower;
msg.cumulusPower = Math.max(0, numOr(ID.power, 0));

// Interrupteur : repli sur le dernier état connu pendant un reboot HA
// (unavailable/unknown), sinon fausse « commande manuelle » en aval.
const rawSwitch = g[ID.switch]?.state;
msg.switchAvailable = rawSwitch === 'on' || rawSwitch === 'off';
msg.switchState = msg.switchAvailable ? rawSwitch : (getF('lastKnownSwitch') || 'off');
if (msg.switchAvailable) setF('lastKnownSwitch', rawSwitch);

// --- Flow clim : consommation qu'il rendrait en s'effaçant ---
// L'eau chaude passe avant le confort : le cumulus « voit à travers » la clim
// pilotée. Attribut absent ou flow clim inexistant : 0.
const ca = g[ID.clim]?.attributes || {};
const rec = parseFloat(ca.recoverable_w);
msg.climRecoverable = isNaN(rec) ? 0 : Math.max(0, rec);
const climMeasured = parseFloat(ca.clim_power_total_w);
msg.climTotal = isNaN(climMeasured) ? msg.climRecoverable : Math.max(0, climMeasured);

// --- Solcast : créneaux 30 min d'aujourd'hui et de demain ---
const sel = g[ID.solcastField]?.state || 'estimate';
msg.forecastField = sel === 'estimate10' ? 'pv_estimate10'
    : sel === 'estimate90' ? 'pv_estimate90' : 'pv_estimate';
const toSlots = (id, day) => (g[id]?.attributes?.detailedForecast || []).map(s => ({
    t: new Date(s.period_start).getTime(),
    pv: (parseFloat(s[msg.forecastField]) || 0) * 1000,
    pv10: (parseFloat(s.pv_estimate10 ?? s[msg.forecastField]) || 0) * 1000,
    day: day
})).filter(s => !isNaN(s.t));
msg.forecastSlots = toSlots(ID.solcastToday, 0).concat(toSlots(ID.solcastTomorrow, 1))
    .sort((a, b) => a.t - b.t);
msg.kwhToday = numOr(ID.solcastToday, 0);
msg.kwhTodayRemaining = numOr(ID.solcastRemaining, 0);
msg.kwhTomorrow = numOr(ID.solcastTomorrow, 0);
msg.kwhTomorrowP10 = attrNum(ID.solcastTomorrow, 'estimate10');
msg.kwhTomorrowP90 = attrNum(ID.solcastTomorrow, 'estimate90');

const lu = g[ID.solcastToday]?.last_updated;
const ageMs = lu ? now - new Date(lu).getTime() : Infinity;
msg.solcastAgeHours = isFinite(ageMs) ? Math.round(ageMs / 360000) / 10 : null;
msg.solcastStale = !(ageMs <= 6 * 3600 * 1000) || msg.forecastSlots.length === 0;

return msg;

// === Bilan instantané et apprentissage de l'installation ===
// Tout ce que le planificateur a besoin de savoir et qu'aucun réglage fixe ne
// décrit bien, appris en continu sur les mesures :
//   - consommation de fond de la maison, heure par heure (hors cumulus, hors clim)
//   - biais de Solcast sur la production réelle (jour courant et long terme)
//   - vitesse de refroidissement du ballon, puisages compris (°C/h)
//   - rendement réel de la chauffe (°C gagnés par kWh consommé)
// Plus le surplus lissé, seule grandeur comparée au seuil du plan : le lissage
// absorbe nuages et bouilloires sans hystérésis de 5 min à attendre.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const now = msg.now;
const MIN_DRAW_W = 100;               // en dessous : résistance non alimentée
const STARTUP_GRACE_MS = 60 * 1000;   // compteur pas encore rafraîchi après turn_on
const SMOOTH_TAU_MS = 3 * 60 * 1000;  // constante de temps du surplus lissé

// Pas de temps depuis la dernière exécution (borné : reprise après coupure)
const lastRun = getF('learnLastRun');
const dtMs = lastRun ? clamp(now - lastRun, 0, 10 * 60000) : 0;
setF('learnLastRun', now);
const ema = (prev, sample, tauMs) => {
    if (prev == null || isNaN(prev)) return sample;
    const a = 1 - Math.exp(-dtMs / tauMs);
    return prev + a * (sample - prev);
};

// --- Consommation réelle du cumulus ---
// Interrupteur ON mais puissance nulle hors période de grâce : thermostat
// mécanique ouvert (ballon plein à son réglage), la résistance ne chauffe pas.
const lastAction = getF('lastAction');
const lastActionAt = getF('lastActionAt') || 0;
const justTurnedOn = lastAction === 'turn_on' && msg.switchState === 'on'
    && (now - lastActionAt) < STARTUP_GRACE_MS;
let draw = 0;
msg.thermostatTripped = false;
if (msg.switchState === 'on') {
    if (msg.cumulusPower >= MIN_DRAW_W) draw = msg.cumulusPower;
    else if (justTurnedOn) draw = msg.loadW;
    else msg.thermostatTripped = true;
}
msg.cumulusDraw = Math.round(draw);
msg.heating = draw > 0;

// --- Surplus potentiel : ce qui serait exporté sans le cumulus ---
// « own » : sans le cumulus seul (stockage au-delà de la cible, le confort
// passe d'abord). « withClim » : en effaçant aussi la clim pilotée (besoin réel
// d'eau chaude, prioritaire sur le confort).
const potOwn = msg.export + draw;
const potWithClim = potOwn + msg.climRecoverable;
const prevOwn = getF('surplusAvgOwn');
const prevClim = getF('surplusAvgClim');
// Changement d'état du relais : le surplus potentiel est continu par
// construction, le lissage n'a pas à repartir de zéro.
const avgOwn = ema(prevOwn, potOwn, SMOOTH_TAU_MS);
const avgClim = ema(prevClim, potWithClim, SMOOTH_TAU_MS);
setF('surplusAvgOwn', avgOwn);
setF('surplusAvgClim', avgClim);
msg.potentialSurplus = Math.round(potWithClim);
msg.potentialOwn = Math.round(potOwn);
msg.surplusAvgOwn = Math.round(avgOwn);
msg.surplusAvgClim = Math.round(avgClim);

// --- Consommation de fond, profil horaire ---
// Maison moins cumulus moins clim : ce qui mange la production avant tout
// pilotage. Une case par heure, chacune ne bouge que pendant son heure : en
// quelques jours le profil reflète la vie de la maison (repas, télétravail…).
const DEFAULT_BASE_W = 250;
let profile = getF('baseProfile');
if (!Array.isArray(profile) || profile.length !== 24) profile = new Array(24).fill(DEFAULT_BASE_W);
const hour = new Date(now).getHours();
const baseSample = clamp(msg.house - draw - msg.climTotal, 0, 5000);
if (dtMs > 0) {
    profile[hour] = Math.round(ema(profile[hour], baseSample, 3600 * 1000));
    setF('baseProfile', profile);
}
msg.baseProfile = profile;
msg.baseNow = Math.round(baseSample);

// --- Biais Solcast ---
// Rapport production mesurée / prévue sur le créneau courant, en journée.
// Jour courant : réactif (45 min), repart chaque matin du biais long terme.
// Long terme : lent (≈ 3 jours de soleil), appliqué aux créneaux de demain.
const slotNow = (msg.forecastSlots || []).find(s => now >= s.t && now < s.t + 1800000);
const dayKey = new Date(now).toDateString();
let biasLong = getF('solcastBiasLong');
if (biasLong == null) biasLong = 1;
let biasToday = getF('solcastBiasToday');
if (getF('solcastBiasDay') !== dayKey) {
    setF('solcastBiasDay', dayKey);
    biasToday = biasLong;
}
if (slotNow && slotNow.pv >= 150 && !msg.solcastStale && dtMs > 0) {
    const ratio = clamp(msg.solar / slotNow.pv, 0.2, 2);
    biasToday = ema(biasToday, ratio, 45 * 60000);
    biasLong = ema(biasLong, ratio, 3 * 8 * 3600 * 1000);
}
msg.biasToday = Math.round(clamp(biasToday == null ? 1 : biasToday, 0.2, 2) * 1000) / 1000;
msg.biasLong = Math.round(clamp(biasLong, 0.3, 1.5) * 1000) / 1000;
setF('solcastBiasToday', msg.biasToday);
setF('solcastBiasLong', msg.biasLong);
msg.forecastNowW = slotNow ? Math.round(slotNow.pv) : null;

// --- Refroidissement du ballon (pertes + puisages), °C/h ---
// Mesuré par tranches d'une heure sans chauffe. Une chauffe remet la référence.
const DEFAULT_DECAY = 0.25;
let decay = getF('decayRate');
if (decay == null) decay = DEFAULT_DECAY;
if (msg.tempAvailable) {
    let ref = getF('decayRef');
    if (msg.heating || !ref) {
        ref = { t: now, temp: msg.temp };
    } else if (now - ref.t >= 3600 * 1000) {
        const h = (now - ref.t) / 3600000;
        const rate = clamp((ref.temp - msg.temp) / h, 0, 4);
        // ≈ 2 jours de mémoire : un bain isolé ne fausse pas tout le plan
        decay = decay + (1 - Math.exp(-h / 48)) * (rate - decay);
        ref = { t: now, temp: msg.temp };
    }
    setF('decayRef', ref);
}
setF('decayRate', decay);
msg.decayRate = Math.round(clamp(decay, 0.02, 4) * 1000) / 1000;

// --- Rendement de chauffe ---
// Session de chauffe = suite de ticks avec résistance alimentée. En fin de
// session d'au moins 0,4 kWh et 1,5 °C, rendement = énergie thermique gagnée
// (volume × ΔT) / énergie électrique consommée. La sonde du ballon ne voit
// qu'une strate : ce « rendement » corrige aussi sa position, d'où l'intérêt
// de l'apprendre plutôt que de le supposer.
let sess = getF('heatSession');
let effLearned = getF('effLearned');
let effSamples = getF('effSamples') || 0;
if (msg.heating && msg.tempAvailable) {
    if (!sess) sess = { startTemp: msg.temp, kwh: 0 };
    sess.kwh += draw * dtMs / 3600000 / 1000;
    sess.lastTemp = msg.temp;
} else if (sess) {
    const dT = (sess.lastTemp != null ? sess.lastTemp : sess.startTemp) - sess.startTemp;
    if (sess.kwh >= 0.4 && dT >= 1.5) {
        const sample = clamp(msg.kwhPerDeg * dT / sess.kwh, 0.3, 1);
        effLearned = effLearned == null ? sample : effLearned + 0.3 * (sample - effLearned);
        effSamples++;
        setF('effLearned', effLearned);
        setF('effSamples', effSamples);
    }
    sess = null;
}
setF('heatSession', sess);
msg.effLearned = effLearned == null ? null : Math.round(effLearned * 100) / 100;
msg.effSamples = effSamples;
// Réglage utilisateur tant que l'apprentissage n'a pas trois sessions
msg.eff = (effLearned != null && effSamples >= 3) ? clamp(effLearned, 0.3, 1) : msg.effSetting;
msg.effSource = (effLearned != null && effSamples >= 3) ? 'appris' : 'réglage';

// --- Bilan énergétique du jour ---
// Part solaire instantanée de la chauffe = min(1, surplus potentiel / tirage).
let day = getF('energyDay');
if (!day || day.key !== dayKey) day = { key: dayKey, heatKwh: 0, solarKwh: 0 };
if (draw > 0 && dtMs > 0) {
    const kwh = draw * dtMs / 3600000 / 1000;
    const share = clamp(potOwn / draw, 0, 1);
    day.heatKwh += kwh;
    day.solarKwh += kwh * share;
}
setF('energyDay', day);
msg.heatKwhToday = Math.round(day.heatKwh * 100) / 100;
msg.solarKwhToday = Math.round(day.solarKwh * 100) / 100;
msg.solarShareToday = day.heatKwh > 0.05 ? Math.round(day.solarKwh / day.heatKwh * 100) : null;

return msg;

// === Planification de la chauffe sur la prévision solaire ===
// Contrat Base, export non rémunéré : un kWh exporté ne vaut rien, un kWh
// réseau coûte le même prix à toute heure. Chauffer coûte donc
//     kWh réseau = tirage du cumulus − surplus disponible pendant la chauffe
// et le bon moment est celui où le surplus attendu est le plus grand.
//
// Pour chaque besoin (minimum garanti, cible de confort, cycle anti-légionelle),
// on répartit l'énergie à fournir sur les créneaux Solcast restants avant son
// échéance, en prenant d'abord les créneaux au plus fort surplus attendu
// (production × biais appris − consommation de fond apprise). Le surplus du
// dernier créneau retenu devient le SEUIL du besoin : chauffer maintenant dès
// que le surplus mesuré l'atteint est aussi bon que le plan.
//   - Besoin faible, beau temps devant : seuil haut, on attend le pic.
//   - Besoin fort ou ciel bouché : seuil bas, chauffe avec une part de réseau.
//   - Échéance imminente sans soleil : seuil nul, chauffe immédiate.
// Le refroidissement appris du ballon est pris en compte : attendre coûte des
// degrés, donc de l'énergie.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const r1 = (v) => Math.round(v * 10) / 10;
const r2 = (v) => Math.round(v * 100) / 100;
const now = msg.now;
const H = 3600000;
const SLOT_MS = 30 * 60000;

const LEGIO_TEMP_REACHED = 60;   // °C validant un cycle
const LEGIO_GOAL = 61;           // °C visés (marge sur la strate de la sonde)
const LEGIO_DUE_DAYS = 7;
const LEGIO_DEADLINE_DAYS = 10;
const FLOOR_DEADBAND = 2;        // °C au-dessus du minimum visés par le filet
const STORAGE_COVER = 0.9;       // part solaire exigée pour stocker au-delà de la cible
const COMFORT_MIN_SHARE = 0.15;  // part solaire minimale d'un créneau de confort
const MAX_HORIZON_MS = 48 * H;

// --- Anti-légionelle : échéance plutôt que forçage aveugle ---
let lastHigh = getF('lastHighTempAt');
if (!lastHigh) { lastHigh = now; setF('lastHighTempAt', now); }   // pas de « dû » fantôme au déploiement
if (msg.tempAvailable && msg.temp >= LEGIO_TEMP_REACHED) {
    lastHigh = now;
    setF('lastHighTempAt', now);
}
msg.daysSinceHighTemp = r1((now - lastHigh) / (24 * H));
msg.legionellaDue = now - lastHigh > LEGIO_DUE_DAYS * 24 * H;
msg.legionellaDeadline = lastHigh + LEGIO_DEADLINE_DAYS * 24 * H;
msg.legionellaOverdue = msg.legionellaDue && now >= msg.legionellaDeadline;

// --- Cibles ---
msg.reachFor = msg.legionellaDue ? Math.max(msg.target, LEGIO_GOAL) : msg.target;
msg.stopTemp = Math.min(msg.minT + FLOOR_DEADBAND, msg.target);
msg.solarSufficientThreshold = r1(msg.target + msg.solarMargin);
msg.solarCoversTarget = msg.solarTankAvailable === true
    && msg.solarTankTemp >= msg.solarSufficientThreshold;

// --- Créneaux : surplus attendu par créneau ---
const base = msg.baseProfile || new Array(24).fill(250);
const slots = (msg.forecastSlots || [])
    .filter(s => s.t + SLOT_MS > now)
    .map(s => {
        const bias = s.day === 0 ? msg.biasToday : msg.biasLong;
        const b = base[new Date(s.t).getHours()] || 0;
        return {
            t: s.t,
            day: s.day,
            exp: Math.max(0, s.pv * bias - b),
            exp10: Math.max(0, s.pv10 * Math.min(bias, 1) - b)
        };
    });
const lastSlotEnd = slots.length ? slots[slots.length - 1].t + SLOT_MS : now;
msg.forecastUsable = !msg.solcastStale && slots.length > 0;

// Énergie thermique (kWh) à apporter pour passer de `from` à `goal` °C
const thermalNeed = (from, goal) => Math.max(0, goal - from) * msg.kwhPerDeg;

/**
 * Répartit un besoin sur les meilleurs créneaux avant l'échéance.
 *   pessimistic : percentile bas de Solcast (filets de sécurité)
 *   minExp      : surplus attendu minimal d'un créneau retenu. Le confort ne
 *                 chauffe qu'au soleil (contrat Base : chauffer sur le réseau
 *                 maintenant ou plus tard coûte pareil, autant ne pas le faire
 *                 pour une cible qui n'est pas un minimum).
 * Retourne :
 *   threshold   : surplus (W) à partir duquel chauffer maintenant vaut le plan
 *   thresholdOn : seuil de maintien, celui du créneau suivant (une chauffe
 *                 engagée ne s'interrompt pas dès que le besoin restant fond)
 *   nowPicked   : le créneau courant fait partie du plan (seuil nul : c'est
 *                 l'heure, à surplus égal on chauffe au plus près de l'échéance
 *                 pour limiter les pertes)
 */
function plan(goal, deadline, pessimistic, minExp) {
    const dl = Math.min(deadline, now + MAX_HORIZON_MS);
    const out = { goal: goal, deadline: dl };
    if (!msg.tempAvailable) return null;
    if (thermalNeed(msg.temp, goal) <= 0) return null;

    // Repli sans prévision exploitable : demi-solaire, puis immédiat à l'approche
    if (!msg.forecastUsable) {
        out.threshold = (dl - now) < 2 * H ? 0 : Math.round(msg.loadW * 0.5);
        out.thresholdOn = out.threshold;
        out.nowPicked = out.threshold === 0;
        out.needKwh = r2(thermalNeed(msg.temp - msg.decayRate * (dl - now) / H / 2, goal) / msg.eff);
        out.fallback = true;
        out.slots = [];
        return out;
    }

    const cands = slots
        .filter(s => s.t < dl)
        .map(s => {
            const start = Math.max(s.t, now);
            const end = Math.min(s.t + SLOT_MS, dl);
            return { t: s.t, start: start, h: Math.max(0, end - start) / H,
                exp: pessimistic ? s.exp10 : s.exp };
        })
        .filter(s => s.h > 0 && s.exp >= (minExp || 0))
        // À surplus égal, le plus tard : moins de pertes avant usage
        .sort((a, b) => b.exp - a.exp || b.t - a.t);
    if (cands.length === 0 && minExp) return null;

    // Deux passes : le besoin dépend du moment de la chauffe (refroidissement).
    let tMean = now;
    let picked = [], need = 0, got = 0;
    for (let pass = 0; pass < 2; pass++) {
        const tempThen = msg.temp - msg.decayRate * Math.max(0, tMean - now) / H;
        need = thermalNeed(tempThen, goal);
        picked = [];
        got = 0;
        for (const s of cands) {
            if (got >= need) break;
            picked.push(s);
            got += msg.loadW / 1000 * s.h * msg.eff;
        }
        const w = picked.reduce((a, s) => a + s.h, 0);
        tMean = w > 0 ? picked.reduce((a, s) => a + (s.start + s.h * H / 2) * s.h, 0) / w : now;
    }
    // Besoin plus grand que tous les créneaux réunis : chauffe dès maintenant
    // pour un filet de sécurité ; pour le confort, au moindre surplus utile.
    const shortfall = got < need;
    const last = picked[picked.length - 1];
    const next = cands[picked.length];
    if (shortfall && !minExp) {
        out.threshold = 0;
        out.nowPicked = true;
    } else {
        out.threshold = last ? Math.round(last.exp) : 0;
        out.nowPicked = picked.some(s => s.start === now || (s.t <= now && now < s.t + SLOT_MS));
    }
    out.thresholdOn = next ? Math.min(out.threshold, Math.round(next.exp)) : out.threshold;
    out.needKwh = r2(need / msg.eff);
    out.freeKwh = r2(picked.reduce((a, s) => a + Math.min(s.exp, msg.loadW) * s.h, 0) / 1000);
    out.gridKwh = r2(Math.max(0, out.needKwh - out.freeKwh));
    out.shortfall = shortfall;
    out.slots = picked.map(s => s.t).sort((a, b) => a - b);
    out.firstSlot = out.slots.length ? out.slots[0] : null;
    return out;
}

const plans = [];

// 1. Minimum garanti : échéance = moment où le refroidissement atteint min_temp.
//    Déjà dessous : immédiat (seuil nul). Prévision pessimiste (p10).
//    Inutile si le ballon solaire amont fournit déjà l'eau à la cible.
if (msg.tempAvailable && msg.temp < msg.stopTemp && !msg.solarCoversTarget) {
    const deadline = msg.temp <= msg.minT ? now
        : now + (msg.temp - msg.minT) / Math.max(msg.decayRate, 0.02) * H;
    const p = plan(msg.stopTemp, deadline, true, 0);
    if (p) plans.push(Object.assign(p, { id: 'floor', label: 'Minimum garanti', basis: 'clim' }));
}

// 2. Anti-légionelle : échéance au 10e jour. Le plan va chercher le meilleur
//    soleil d'ici là ; échéance passée, seuil nul.
if (msg.legionellaDue && msg.tempAvailable && msg.temp < LEGIO_GOAL) {
    const p = plan(LEGIO_GOAL, msg.legionellaOverdue ? now : msg.legionellaDeadline, false, 0);
    if (p) plans.push(Object.assign(p, { id: 'legionella', label: 'Anti-légionelle', basis: 'clim' }));
}

// 3. Confort : cible atteinte d'ici la fin de la prévision (demain soir), au
//    soleil seulement. Inutile si le ballon solaire amont fournit déjà l'eau.
if (!msg.solarCoversTarget) {
    const p = plan(msg.target, lastSlotEnd, false, msg.loadW * COMFORT_MIN_SHARE);
    if (p) plans.push(Object.assign(p, { id: 'comfort', label: 'Cible de confort', basis: 'clim' }));
}

// 4. Stockage : chaleur quasi gratuite toujours prise, sans plafond logiciel
//    (le thermostat mécanique coupe). Le confort de la clim passe avant : seuil
//    comparé au surplus SANS effacer la clim.
const storageW = Math.round(msg.loadW * STORAGE_COVER);
plans.push({ id: 'storage', label: 'Stockage gratuit', basis: 'own',
    threshold: storageW, thresholdOn: storageW, nowPicked: false, slots: [] });

msg.plans = plans;

// Créneaux retenus du besoin le plus contraignant, pour l'affichage
const needPlans = plans.filter(p => p.id !== 'storage');
const lead = needPlans.slice().sort((a, b) => (b.nowPicked - a.nowPicked) || a.threshold - b.threshold)[0] || null;
msg.leadPlan = lead ? lead.id : null;
msg.plannedSlots = lead ? lead.slots : [];
msg.needKwh = lead ? lead.needKwh : 0;
msg.planGridKwh = lead && lead.gridKwh != null ? lead.gridKwh : 0;

// Surplus attendu sur le reste de la journée, pour l'affichage
msg.expectedSurplusKwh = r1(slots.filter(s => s.day === 0)
    .reduce((a, s) => a + s.exp * (s.t + SLOT_MS - Math.max(s.t, now)) / H, 0) / 1000);

return msg;

// === Décision : échelle de priorités, de haut en bas ===
//   1. Automatisation désactivée        → aucune commande
//   2. Pause manuelle (45 min)           → aucune commande
//   3. Interrupteur illisible            → aucune commande
//   4. Sonde du ballon HS                → stockage gratuit seulement
//   5. Anti-légionelle échue             → chauffe immédiate
//   6. Plans (minimum, légionelle, confort, stockage)
//                                         → chauffe si le surplus lissé atteint
//                                           le seuil d'un des plans
//   7. Anti court-cycle du relais        → état maintenu le temps du minimum
// Chaque étape est publiée dans decision_path, la carte affiche le chemin.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const now = msg.now;
const MANUAL_HOLD_MS = 45 * 60000;
const HA_LAG_GRACE_MS = 90 * 1000;
const MIN_ON_MS = 5 * 60000;
const MIN_OFF_MS = 3 * 60000;
const HYST_W = 150;               // tolérance à l'arrêt, sous le seuil

const path = [];
const step = (id, label, status, detail) => path.push({ id, label, status, detail: detail || null });
let decided = false;
const decide = (desired, state, reason, ruleId) => {
    msg.desired = desired;
    msg.state = state;
    msg.reason = reason;
    msg.rule = ruleId;
    decided = true;
};
const on = msg.switchState === 'on';

// --- Détection d'une commande manuelle ---
// Interrupteur changé hors du flow (HA, bouton physique) : pause 45 min.
// Ignorée tant que l'état est illisible (reboot HA).
let expected = getF('expectedSwitch');
if (expected == null && msg.switchAvailable) { expected = msg.switchState; setF('expectedSwitch', expected); }
const lastActionAt = getF('lastActionAt') || 0;
let holdUntil = getF('manualHoldUntil') || 0;
if (msg.switchAvailable && expected != null && msg.switchState !== expected
    && now - lastActionAt > HA_LAG_GRACE_MS) {
    holdUntil = now + MANUAL_HOLD_MS;
    setF('manualHoldUntil', holdUntil);
    setF('expectedSwitch', msg.switchState);
    node.warn('Commande manuelle détectée → pause automatisation 45 min');
}
msg.manualHoldActive = now < holdUntil;
msg.manualHoldUntil = msg.manualHoldActive ? holdUntil : null;
const hhmm = (t) => new Date(t).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });

// 1. Automatisation
if (!msg.enabled) {
    step('enabled', 'Automatisation active', 'hit', 'désactivée');
    decide(msg.switchState, 'Désactivé', 'Automatisation désactivée, aucune commande envoyée', 'enabled');
} else step('enabled', 'Automatisation active', 'pass');

// 2. Pause manuelle
if (!decided) {
    if (msg.manualHoldActive) {
        step('manual', 'Pas de commande manuelle', 'hit', 'reprise à ' + hhmm(holdUntil));
        decide(msg.switchState, 'Pause (commande manuelle)',
            'Intervention manuelle détectée, reprise à ' + hhmm(holdUntil), 'manual');
    } else step('manual', 'Pas de commande manuelle', 'pass');
}

// 3. Interrupteur
if (!decided) {
    if (!msg.switchAvailable) {
        step('switch', 'Interrupteur joignable', 'hit', 'état illisible');
        decide(msg.switchState, 'Interrupteur injoignable',
            'État de l\'interrupteur illisible, aucune commande', 'switch');
    } else step('switch', 'Interrupteur joignable', 'pass');
}

// Comparaison d'un plan au surplus lissé, avec tolérance à l'arrêt
// Thermostat mécanique ouvert, relais fermé : la résistance absorbera le surplus
// dès que le thermostat refermera, sans rien coûter d'ici là. Son tirage
// nominal est compté pour ne pas faire battre le relais.
const virtual = on && msg.thermostatTripped ? msg.loadW : 0;
const surplusFor = (p) => (p.basis === 'own' ? msg.surplusAvgOwn : msg.surplusAvgClim) + virtual;
// Seuil nul : le plan chauffe sans condition de surplus, mais seulement quand
// le créneau courant est retenu (la nuit, le surplus mesuré est négatif).
// Chauffe engagée : seuil du créneau suivant du plan, moins une tolérance.
const thresholdUsed = (p) => (on
    ? Math.min(p.threshold, p.thresholdOn != null ? p.thresholdOn : p.threshold) - HYST_W
    : p.threshold);
const satisfied = (p) => {
    if (p.threshold <= 0) return p.nowPicked === true;
    return surplusFor(p) >= thresholdUsed(p);
};

// 4. Sonde HS : sans température, seul le stockage gratuit reste sûr
msg.degradedSonde = !msg.tempAvailable;
if (!decided) {
    if (msg.degradedSonde) {
        const st = msg.plans.find(p => p.id === 'storage');
        const ok = satisfied(st);
        step('sensor', 'Sonde du ballon', 'hit', 'HS depuis ' + msg.sondeDownHours + ' h');
        decide(ok ? 'on' : 'off', ok ? 'Chauffage (stockage, sonde HS)' : 'Veille (sonde HS)',
            ok ? 'Sonde HS, surplus quasi gratuit ' + msg.surplusAvgOwn + ' W ≥ ' + st.threshold + ' W'
                : 'Sonde HS, seul le surplus quasi gratuit est utilisé', 'sensor');
    } else step('sensor', 'Sonde du ballon', 'pass', msg.temp + ' °C');
}

// 5. Anti-légionelle échue
msg.legionellaCritical = msg.legionellaOverdue && msg.tempAvailable && msg.temp < 61;
msg.legionellaBlocked = msg.legionellaCritical && msg.thermostatTripped;
if (!decided) {
    if (msg.legionellaCritical) {
        step('legionella_overdue', 'Légionelle à jour', 'hit',
            msg.daysSinceHighTemp + ' j sans 60 °C');
        decide('on', 'Chauffage (anti-légionelle)',
            msg.daysSinceHighTemp + ' j sans 60 °C, échéance dépassée : chauffe immédiate', 'legionella_overdue');
    } else step('legionella_overdue', 'Légionelle à jour', 'pass',
        msg.legionellaDue ? 'cycle dû, planifié' : msg.daysSinceHighTemp + ' j');
}

// 6. Plans
msg.planEval = msg.plans.map(p => ({
    id: p.id, threshold: p.threshold, surplus: surplusFor(p), ok: satisfied(p)
}));
if (!decided) {
    const hit = msg.plans.find(p => satisfied(p));
    for (const p of msg.plans) {
        const s = surplusFor(p);
        const detail = s + ' / ' + (p.threshold > 0 ? thresholdUsed(p) + ' W' : 'immédiat');
        if (decided) { step('plan_' + p.id, p.label, 'skip', detail); continue; }
        if (p === hit) {
            step('plan_' + p.id, p.label, 'hit', detail);
            const why = p.threshold <= 0
                ? (p.id === 'floor' ? 'eau sous le minimum, chauffe immédiate'
                    : 'échéance proche, plus de meilleur créneau')
                : 'surplus ' + s + ' W ≥ seuil ' + thresholdUsed(p) + ' W'
                    + (on && thresholdUsed(p) < p.threshold ? ' (maintien)' : '');
            const states = {
                floor: 'Chauffage (minimum garanti)',
                legionella: 'Chauffage (anti-légionelle)',
                comfort: 'Chauffage (solaire)',
                storage: 'Chauffage (stockage gratuit)'
            };
            decide('on', states[p.id], p.label + ' : ' + why, 'plan_' + p.id);
        } else {
            step('plan_' + p.id, p.label, 'pass', detail);
        }
    }
    if (!decided) {
        // Rien à faire maintenant : expliquer ce qu'on attend
        const pending = msg.plans.filter(p => p.id !== 'storage');
        if (pending.length === 0) {
            const why = msg.solarCoversTarget
                ? 'Ballon solaire amont à ' + msg.solarTankTemp + ' °C, appoint inutile'
                : 'Eau à ' + msg.temp + ' °C, cible ' + msg.target + ' °C atteinte';
            decide('off', msg.solarCoversTarget ? 'Solaire amont suffisant' : 'Cible atteinte', why, 'idle');
        } else {
            const p = pending.slice().sort((a, b) => a.threshold - b.threshold)[0];
            const next = p.firstSlot && p.firstSlot > now ? ', prochain créneau ' + hhmm(p.firstSlot) : '';
            decide('off', 'Veille (attente soleil)',
                p.label + ' : surplus ' + surplusFor(p) + ' W < seuil ' + p.threshold + ' W' + next, 'wait');
        }
    }
}

// 7. Anti court-cycle du relais
msg.shortCycleHold = false;
if (msg.enabled && !msg.manualHoldActive && msg.switchAvailable && msg.desired !== msg.switchState
    && msg.rule !== 'legionella_overdue' && !(msg.rule === 'plan_floor' && msg.temp <= msg.minT)) {
    const lastAt = getF('lastActionAt') || 0;
    const minMs = on ? MIN_ON_MS : MIN_OFF_MS;
    if (now - lastAt < minMs) {
        const left = Math.ceil((minMs - (now - lastAt)) / 60000);
        step('short_cycle', 'Anti court-cycle', 'hit', left + ' min');
        msg.shortCycleHold = true;
        msg.reason = msg.reason + ' (appliqué dans ' + left + ' min, anti court-cycle)';
        msg.desired = msg.switchState;
    }
}

msg.decisionPath = path;
return msg;

// === Action et historique ===
// action = turn_on / turn_off / none. Aucune commande vers un interrupteur
// illisible : elle échouerait et fausserait l'historique.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const now = msg.now;
msg.action = 'none';
if (msg.switchAvailable && msg.desired !== msg.switchState) {
    msg.action = msg.desired === 'on' ? 'turn_on' : 'turn_off';
    setF('lastActionAt', now);
    setF('lastAction', msg.action);
    setF('lastActionReason', msg.reason);
    setF('expectedSwitch', msg.desired);
}
msg.lastActionAt = getF('lastActionAt');
msg.lastAction = getF('lastAction');
msg.lastActionReason = getF('lastActionReason');

// Sortie 1 : commande de l'interrupteur, cible portée par le message (entité
// de l'onglet Env, aucune entité en dur dans les nœuds de service).
// Sortie 2 : synthèse, vers le sensor et les alertes.
const cmd = msg.action === 'none' ? null : {
    action: msg.action,
    reason: msg.reason,
    payload: { target: { entity_id: msg.switchId } }
};
return [cmd, msg];

// === Alertes HA (persistent_notification) ===
// Une notification par épisode, anti-spam via contexte persistant.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const out = [];
const now = msg.now;
const DAY_MS = 24 * 3600 * 1000;

// 1. Sonde HS depuis ≥ 2 h
if ((msg.sondeDownHours || 0) >= 2) {
    if (!getF('notifSondeDown')) {
        setF('notifSondeDown', true);
        out.push({ payload: {
            notification_id: 'cumulus_sonde_hs',
            title: 'Cumulus : sonde température HS',
            message: 'Sonde indisponible depuis ' + msg.sondeDownHours
                + ' h. Seul le surplus quasi gratuit chauffe l\'eau, aucun minimum garanti.'
        }});
    }
} else if (msg.tempAvailable) {
    setF('notifSondeDown', false);
}

// 2. Cycle anti-légionelle forcé malgré un thermostat mécanique ouvert
if (msg.legionellaBlocked) {
    const last = getF('notifLegioBlockedAt') || 0;
    if (now - last > DAY_MS) {
        setF('notifLegioBlockedAt', now);
        out.push({ payload: {
            notification_id: 'cumulus_legio_blocked',
            title: 'Cumulus : anti-légionelle bloquée par le thermostat',
            message: msg.daysSinceHighTemp + ' j sans 60 °C. Relais fermé mais le thermostat '
                + 'mécanique coupe avant 60 °C (eau à ' + msg.temp + ' °C). Réglage du '
                + 'thermostat à vérifier.'
        }});
    }
}

// 3. Prévision Solcast inexploitable depuis ≥ 12 h : le plan tourne en repli
if (msg.solcastStale && (msg.solcastAgeHours == null || msg.solcastAgeHours >= 12)) {
    const last = getF('notifSolcastAt') || 0;
    if (now - last > DAY_MS) {
        setF('notifSolcastAt', now);
        out.push({ payload: {
            notification_id: 'cumulus_solcast',
            title: 'Cumulus : prévision Solcast inexploitable',
            message: 'Aucune prévision récente ('
                + (msg.solcastAgeHours == null ? 'absente' : msg.solcastAgeHours + ' h')
                + '). Planification en repli : chauffe dès 50 % de part solaire.'
        }});
    }
}

if (out.length === 0) return null;
return [out];

// === Gestion des erreurs du flow (nœud catch) ===

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const src = (msg.error && msg.error.source) || {};
// Nœuds de commande de l'interrupteur, repérés par leur nom : un identifiant
// en dur ne survit pas à un réimport avec renumérotation.
const SWITCH_NODES = ['switch.turn_on', 'switch.turn_off'];

// Commande échouée : l'historique optimiste est faux → purge, sinon la période
// de grâce et la détection manuelle dérivent.
if (SWITCH_NODES.indexOf(src.name) !== -1) {
    setF('lastAction', null);
    setF('lastActionAt', 0);
    setF('expectedSwitch', null);
}

// Anti-spam : 1 notification max / 15 min
const now = Date.now();
const last = getF('lastErrorNotifAt') || 0;
if (now - last < 15 * 60 * 1000) return null;
setF('lastErrorNotifAt', now);

msg.payload = {
    notification_id: 'cumulus_flow_error',
    title: 'Cumulus : erreur dans le flow',
    message: (src.name || src.id || '?') + ' : '
        + (msg.error && msg.error.message ? msg.error.message : 'erreur inconnue')
};
return msg;
